CREATE DATABASE IF NOT EXISTS yeha_group CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE yeha_group;
CREATE TABLE roles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(40) UNIQUE NOT NULL) ENGINE=InnoDB;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,phone VARCHAR(40),password_hash VARCHAR(255) NOT NULL,role_id BIGINT UNSIGNED NOT NULL,status ENUM('active','pending','suspended','disabled') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE customer_profiles(user_id BIGINT UNSIGNED PRIMARY KEY,company_name VARCHAR(160),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE technician_profiles(user_id BIGINT UNSIGNED PRIMARY KEY,specialization VARCHAR(160),experience_years SMALLINT DEFAULT 0,verification_status ENUM('pending','verified','rejected','suspended') DEFAULT 'pending',availability_status ENUM('available','busy','unavailable') DEFAULT 'unavailable',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE technician_applications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120),email VARCHAR(190),phone VARCHAR(40),specialization VARCHAR(160),experience_years SMALLINT DEFAULT 0,skills TEXT,status ENUM('submitted','under_review','shortlisted','approved','rejected') DEFAULT 'submitted',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(email),INDEX(status)) ENGINE=InnoDB;
CREATE TABLE service_categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) UNIQUE NOT NULL,description TEXT,is_active TINYINT DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE services(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED,name VARCHAR(160) NOT NULL,description TEXT,base_price DECIMAL(12,2),currency CHAR(3) DEFAULT 'ETB',is_active TINYINT DEFAULT 1,FOREIGN KEY(category_id) REFERENCES service_categories(id)) ENGINE=InnoDB;
CREATE TABLE service_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,service_id BIGINT UNSIGNED NOT NULL,description TEXT,preferred_date DATE,address TEXT,latitude DECIMAL(10,7),longitude DECIMAL(10,7),status ENUM('submitted','under_review','quoted','approved','assigned','in_progress','completed','cancelled','rejected') DEFAULT 'submitted',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES users(id),FOREIGN KEY(service_id) REFERENCES services(id),INDEX(status),INDEX(customer_id)) ENGINE=InnoDB;
CREATE TABLE service_assignments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id BIGINT UNSIGNED NOT NULL,technician_id BIGINT UNSIGNED NOT NULL,status ENUM('offered','accepted','rejected','traveling','arrived','working','completed','cancelled') DEFAULT 'offered',assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(request_id) REFERENCES service_requests(id),FOREIGN KEY(technician_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE appointments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id BIGINT UNSIGNED NOT NULL,scheduled_at DATETIME NOT NULL,status ENUM('scheduled','rescheduled','completed','cancelled','no_show') DEFAULT 'scheduled',FOREIGN KEY(request_id) REFERENCES service_requests(id)) ENGINE=InnoDB;
CREATE TABLE technician_locations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,assignment_id BIGINT UNSIGNED NOT NULL,technician_id BIGINT UNSIGNED NOT NULL,latitude DECIMAL(10,7),longitude DECIMAL(10,7),recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(assignment_id) REFERENCES service_assignments(id),FOREIGN KEY(technician_id) REFERENCES users(id),INDEX(assignment_id,recorded_at)) ENGINE=InnoDB;
CREATE TABLE messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sender_id BIGINT UNSIGNED NOT NULL,recipient_id BIGINT UNSIGNED NOT NULL,message TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(sender_id) REFERENCES users(id),FOREIGN KEY(recipient_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,title VARCHAR(180),body TEXT,read_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE support_tickets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,subject VARCHAR(180),message TEXT,status ENUM('open','in_progress','resolved','closed') DEFAULT 'open',FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id BIGINT UNSIGNED,customer_id BIGINT UNSIGNED,provider VARCHAR(80) DEFAULT 'demo',provider_reference VARCHAR(190),amount DECIMAL(12,2),currency CHAR(3) DEFAULT 'ETB',status ENUM('pending','processing','successful','failed','cancelled','refunded','partially_refunded') DEFAULT 'pending',idempotency_key VARCHAR(100) UNIQUE,verified_at DATETIME,FOREIGN KEY(request_id) REFERENCES service_requests(id),FOREIGN KEY(customer_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE commission_settings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,scope_type ENUM('default','category','technician') DEFAULT 'default',scope_id BIGINT UNSIGNED,rate_percent DECIMAL(5,2) NOT NULL,starts_at DATETIME DEFAULT CURRENT_TIMESTAMP,ends_at DATETIME,is_active TINYINT DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE commission_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,payment_id BIGINT UNSIGNED UNIQUE,technician_id BIGINT UNSIGNED,gross_amount DECIMAL(12,2),rate_snapshot DECIMAL(5,2),company_amount DECIMAL(12,2),technician_amount DECIMAL(12,2),status ENUM('pending','released','reversed') DEFAULT 'pending',FOREIGN KEY(payment_id) REFERENCES payments(id),FOREIGN KEY(technician_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE technician_wallets(technician_id BIGINT UNSIGNED PRIMARY KEY,available_balance DECIMAL(12,2) DEFAULT 0,pending_balance DECIMAL(12,2) DEFAULT 0,FOREIGN KEY(technician_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE wallet_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,technician_id BIGINT UNSIGNED,transaction_type VARCHAR(30),amount DECIMAL(12,2),status VARCHAR(30),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(technician_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE withdrawal_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,technician_id BIGINT UNSIGNED,amount DECIMAL(12,2),payout_method VARCHAR(80),status ENUM('requested','under_review','approved','processing','paid','rejected') DEFAULT 'requested',FOREIGN KEY(technician_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE invoices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id BIGINT UNSIGNED,invoice_number VARCHAR(60) UNIQUE,total DECIMAL(12,2),currency CHAR(3) DEFAULT 'ETB',FOREIGN KEY(request_id) REFERENCES service_requests(id)) ENGINE=InnoDB;
CREATE TABLE financial_ledger(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transaction_group VARCHAR(100),account_code VARCHAR(80),entry_type ENUM('debit','credit'),amount DECIMAL(14,2),currency CHAR(3) DEFAULT 'ETB',reference_type VARCHAR(60),reference_id BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(transaction_group)) ENGINE=InnoDB;
CREATE TABLE job_vacancies(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180),description TEXT,status ENUM('draft','published','closed') DEFAULT 'draft') ENGINE=InnoDB;
CREATE TABLE job_applications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,vacancy_id BIGINT UNSIGNED,full_name VARCHAR(120),email VARCHAR(190),phone VARCHAR(40),cv_path VARCHAR(255),status VARCHAR(30) DEFAULT 'submitted',FOREIGN KEY(vacancy_id) REFERENCES job_vacancies(id)) ENGINE=InnoDB;
CREATE TABLE projects(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180),sector VARCHAR(100),description TEXT,status ENUM('planned','ongoing','completed') DEFAULT 'planned') ENGINE=InnoDB;
CREATE TABLE partners(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180),description TEXT,website VARCHAR(255),logo_path VARCHAR(255)) ENGINE=InnoDB;
CREATE TABLE testimonials(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,person_name VARCHAR(120),organization VARCHAR(160),content TEXT,is_published TINYINT DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE website_pages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,page_key VARCHAR(100) UNIQUE,title VARCHAR(180),content LONGTEXT) ENGINE=InnoDB;
CREATE TABLE contact_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120),email VARCHAR(190),message TEXT,status VARCHAR(30) DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE system_settings(setting_key VARCHAR(120) PRIMARY KEY,setting_value TEXT) ENGINE=InnoDB;
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,action VARCHAR(120),entity_type VARCHAR(80),entity_id BIGINT UNSIGNED,details JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
